function playable(r){if(r.kind==='item')need((g.DecideCatalogItemEffects||(typeof require==='function'?require('./catalog-item-effects'):null)).supported({...r,enabled:true}),'ผลไอเท็มนี้ยังไม่รองรับ');const {A,M,S,Gear}=apis(),enabled={...r,enabled:true};if(['skill','spell'].includes(r.kind))need(A.compile(enabled)||M.compile(enabled),'กลไกของ '+r.name+' ไม่รองรับค่าที่กรอก');if(r.kind==='weapon'){const w=Gear.weapon(enabled);need(w?.dice&&w.type&&['STR','DEX'].includes(r.ability)&&Number.isInteger(r.attackBonus||0)&&Math.abs(r.attackBonus||0)<=20&&Number.isFinite(r.elementDamage||0)&&(r.elementDamage||0)>=0&&(r.elementDamage||0)<=999,'ค่าอาวุธไม่รองรับ');}if(['armor','helmet','boots','accessory'].includes(r.kind))need(Number.isFinite(r.defense??0)&&(r.defense??0)>=0&&(r.defense??0)<=1000,'ค่าป้องกันต้องเป็น 0–1000');if(['weapon','armor','helmet','boots','accessory'].includes(r.kind)&&r.passive){need(typeof r.passive==='string'&&r.passive.split(/[,;\n]/).filter(x=>x.trim()).every(x=>/^(?:STR|DEX|HP|MP|DEF|Defense|ATK|Attack|Crit|Crit Rate|Critical Rate|Resistance|Resist)\s*[:=]?\s*[+-]?\d+(?:\.\d+)?\s*%?$/i.test(x.trim())),'โบนัสอุปกรณ์ใช้รูปแบบ STR +2, HP +10, Crit +5%, Resistance +5%');const b=apis().P.parseEquipmentPassiveEffects(r.passive);need(Object.entries(b).every(([k,n])=>Math.abs(n)<=(['str','dex'].includes(k)?20:['hp','mp'].includes(k)?500:['critRate','resistance'].includes(k)?90:100)),'โบนัสเกินช่วง: STR/DEX 20, HP/MP 500, Crit/Resistance 90, ATK/DEF 100');}if(r.kind==='item'&&['heal_hp','restore_mp'].includes((g.DecideCatalogItemEffects||(typeof require==='function'?require('./catalog-item-effects'):null)).mode(r)))need(Number.isInteger(r.value)&&r.value>0&&r.value<=9999,'ไอเท็มรองรับฟื้น HP/MP จำนวน 1–9999');if(r.kind==='monster'){need(S.compile(enabled),'ค่าสถานะมอนสเตอร์ไม่รองรับ');need(Array.isArray(r.skills)&&r.skills.length<=20,'มอนสเตอร์มีสกิลได้สูงสุด 20');for(const stat of ['str','dex','con','int','wis','cha'])need(Number.isFinite(r[stat])&&r[stat]>=1&&r[stat]<=99,'ค่าสเตตัสต้องอยู่ในช่วง 1–99');}for(const key of ['buyPrice','sellPrice','goldCost'])if(r[key]!==undefined)need(Number.isSafeInteger(r[key])&&r[key]>=0&&r[key]<=1000000,key+' ต้องเป็นจำนวนเต็ม 0–1000000');if(r.kind==='recipe')need(Number.isInteger(r.resultQuantity)&&r.resultQuantity>=1&&r.resultQuantity<=99,'จำนวนผลผลิตต้องเป็น 1–99');return r;}
function validateRegistry(data,bases,schema){need(data&&data.v===1&&Array.isArray(data.records)&&data.records.length<=200,'สร้างข้อมูลใหม่ได้สูงสุด 200 รายการ');safe(data);need(JSON.stringify(data).length<=2000000,'ข้อมูลใหม่ใหญ่เกิน 2 MB');const baseMap=new Map(templates(bases).map(r=>[r.key,r])),ids=new Set(bases.map(r=>r.id)),names=new Set(bases.map(r=>r.name.trim().toLowerCase()));const out=[];for(const input of data.records){need(input&&kinds.includes(input.kind)&&customId(input.id)&&typeof input.name==='string'&&input.name===input.name.trim()&&input.name.length>0&&input.name.length<=120&&!/[\x00-\x1f]/.test(input.name),'ชนิด ID หรือชื่อข้อมูลใหม่ไม่ถูกต้อง');need(!('key'in input),'ไม่ต้องระบุ key ในข้อมูลใหม่');const key=input.kind+':'+input.id;need(!ids.has(input.id)&&!names.has(input.name.toLowerCase()),'ID หรือชื่อซ้ำ: '+input.name);const template=baseMap.get(input.templateKey);need(template&&template.kind===input.kind,'ต้องเลือกแม่แบบที่ใช้ได้จริงและเป็นหมวดเดียวกัน');validateValues(input,template,schema);const normalized={...create(template,input.name,input.id),...copy(input)};if(input.kind==='weapon')need(normalized.type===apis().Gear.weapon(template).type,'เปลี่ยนชนิดอาวุธโดยเลือกแม่แบบใหม่');playable(normalized);ids.add(input.id);names.add(input.name.toLowerCase());out.push(normalized);}return {v:1,records:out};}
function create(template,name,id){const out=copy(template);delete out.key;delete out.displayName;out.id=id;out.name=name.trim();out.templateKey=template.templateKey||template.key;out.enabled=true;if(template.kind==='item'){const Effects=g.DecideCatalogItemEffects||(typeof require==='function'?require('./catalog-item-effects'):null);out.itemAction=Effects.mode(template);}const {A,P}=apis();if(['skill','spell'].includes(template.kind)){const action=A.compile(template);if(action?.effect==='heal'){const d=action.roll,text=d.n+'d'+d.sides+(d.bonus?(d.bonus>0?'+':'')+d.bonus:'');out.healDice=text;if(template.kind==='skill')out.healing=text;}}if(['weapon','armor','helmet','boots','accessory'].includes(template.kind)){const b=P.parseEquipmentPassiveEffects(P.combineEquipmentPassiveText(template)),labels={str:'STR',dex:'DEX',hp:'HP',mp:'MP',defense:'DEF',attack:'ATK',critRate:'Crit',resistance:'Resistance'};out.passive=Object.entries(b).filter(([k,n])=>n!==0).map(([k,n])=>labels[k]+' '+(n>0?'+':'')+n).join(', ');delete out.passiveEffects;delete out.specialEffectsText;}if(template.kind==='weapon')out.type=apis().Gear.weapon(template).type;return out;}
function decode(text){need(typeof text==='string'&&text.length<=2000000,'ไฟล์ข้อมูลต้องไม่เกิน 2 MB');const block=/^```(?:json)?\s*([\s\S]*?)\s*```$/i.exec(text.trim()),value=JSON.parse(block?block[1]:text);safe(value);return value;}
function stage(pack,current,rows){safe(pack);need(pack?.format===FORMAT,'ใช้ไฟล์คำตอบแบบ decide-fate-data-pack-v1');need(pack.baseFingerprint===fingerprint(current),'ฐานข้อมูลเปลี่ยนจากตอนส่งแม่แบบ โปรดส่งแม่แบบล่าสุดให้ AI ใหม่');need(Object.keys(pack).every(k=>['format','baseFingerprint','changes','create'].includes(k)),'ชุดข้อมูลมีช่องที่ไม่รองรับ');need(pack.changes&&typeof pack.changes==='object'&&!Array.isArray(pack.changes)&&Array.isArray(pack.create),'changes ต้องเป็น object และ create ต้องเป็นรายการ');const next=copy(current),registry=copy(current[KEY]||{v:1,records:[]}),created=[];for(const r of pack.create){registry.records.push(copy(r));created.push({key:r.kind+':'+r.id,name:r.name,templateKey:r.templateKey});}if(pack.create.length)next[KEY]=registry;const changed=[];for(const [key,patch]of Object.entries(pack.changes)){const row=rows.find(r=>r.key===key)||pack.create.find(r=>r.kind+':'+r.id===key);need(row&&patch&&typeof patch==='object'&&!Array.isArray(patch),'ไม่พบรายการที่แก้ไข '+key);need(Object.keys(patch).every(k=>!['id','kind','key','name','templateKey'].includes(k)),'ห้ามเปลี่ยน ID ชื่ออ้างอิง หรือแม่แบบ ใช้ displayName สำหรับชื่อที่แสดง');const fields=Object.entries(patch).filter(([k,v])=>JSON.stringify(row[k])!==JSON.stringify(v)).map(([field,after])=>({field,before:row[field],after}));next[key]={...(next[key]||{}),...copy(patch)};if(fields.length)changed.push({key,name:row.displayName||row.name,fields});}need(created.length||changed.length,'ไม่มีข้อมูลที่เปลี่ยน');return {next,created,changed,baseFingerprint:pack.baseFingerprint};}
function request(template,current,schema,rows,id){const fields=fieldsFor(template,schema),newRecord=create(template,'ชื่อใหม่ที่ไม่ซ้ำ',id),allowed=new Set(['id','kind','name','templateKey','enabled',...fields.map(f=>f.key)]),example=Object.fromEntries(Object.entries(newRecord).filter(([k])=>allowed.has(k)));const refs=new Set(fields.filter(f=>f.refType).map(f=>f.refType));if(template.kind==='monster')refs.add('skill');if(['npc','recipe'].includes(template.kind)){for(const kind of ['item','dropItem','weapon','armor','helmet','boots','accessory','npc'])refs.add(kind);}return {instructions:'คุณช่วยกรอกข้อมูลเกมเท่านั้น ไม่แก้โค้ด ไม่ใช้ API ส่งคืน JSON format decide-fate-data-pack-v1 ตาม exampleResponse ห้ามเปลี่ยน baseFingerprint/templateKey ใช้ชนิดตัวเลข/ข้อความ/รายการตาม schema สร้างได้เฉพาะกลไกของแม่แบบนี้ คำบรรยายไม่เพิ่มกลไกใหม่ ช่องที่ไม่ระบุจะใช้ค่าจากแม่แบบ ถ้าไม่รองรับให้บอกผู้ใช้ อย่าแต่งช่องขึ้นเอง create แต่ละรายการต้องมี ID custom- ที่ไม่ซ้ำและชื่ออ้างอิงไม่ซ้ำ การแก้รายการเดิมใช้ changes และชื่อที่แสดงใช้ displayName',template:{key:template.key,kind:template.kind,name:template.name},mechanics:apis().A.compile(template)||apis().M.compile(template)||(template.kind==='weapon'?apis().Gear.weapon(template):{kind:template.kind}),schema:fields.map(f=>({key:f.key,label:f.label,type:f.type,options:f.options,refType:f.refType,byName:f.byName,hint:f.hint,default:f.default})),references:rows.filter(r=>refs.has(r.kind)&&r.enabled!==false).map(r=>({kind:r.kind,id:r.id,name:r.name})),exampleResponse:{format:FORMAT,baseFingerprint:fingerprint(current),changes:{},create:[example]}};}
function restore(current,backup){const next=copy(backup),saved=copy(backup[KEY]||{v:1,records:[]}),keys=new Set(saved.records.map(r=>r.kind+':'+r.id));for(const r of records(current))if(!keys.has(r.key)){const kept={...r,...(current[r.key]||{}),enabled:false};delete kept.key;saved.records.push(kept);}if(saved.records.length)next[KEY]=saved;return next;}
